def find_6_3_2_design_with_both():
    n = 6
    edges = list(itertools.combinations(range(n), 2))
    num_edges = len(edges)
    edge_to_idx = {e: i for i, e in enumerate(edges)}

    triangles = list(itertools.combinations(range(n), 3))
    triangle_edges = []
    for tri in triangles:
        e1 = edge_to_idx[tuple(sorted((tri[0], tri[1])))]
        e2 = edge_to_idx[tuple(sorted((tri[1], tri[2])))]
        e3 = edge_to_idx[tuple(sorted((tri[0], tri[2])))]
        triangle_edges.append((e1, e2, e3))

    idx_012 = -1
    idx_345 = -1
    for i, tri in enumerate(triangles):
        if set(tri) == {0, 1, 2}: idx_012 = i
        if set(tri) == {3, 4, 5}: idx_345 = i

    edge_counts = [0] * num_edges
    for e in triangle_edges[idx_012]: edge_counts[e] += 1
    for e in triangle_edges[idx_345]: edge_counts[e] += 1

    used_triangles = {idx_012, idx_345}

    def backtrack(num_picked):
        if num_picked == 10:
            return all(c == 2 for c in edge_counts)

        # Find the first edge that is not covered 2 times
        target_edge = -1
        for i in range(num_edges):
            if edge_counts[i] < 2:
                target_edge = i
                break

        if target_edge == -1:
            return False # Should not happen if num_picked < 10

        # Find all triangles that include this edge and are not yet used
        for i, tri_e in enumerate(triangle_edges):
            if target_edge in tri_e and i not in used_triangles:
                # Check if adding this triangle is okay
                can_add = True
                for e in tri_e:
                    if edge_counts[e] == 2:
                        can_add = False
                        break
                if can_add:
                    for e in tri_e: edge_counts[e] += 1
                    used_triangles.add(i)
                    if backtrack(num_picked + 1):
                        return True
                    used_triangles.remove(i)
                    for e in tri_e: edge_counts[e] -= 1
        return False

    if backtrack(2):
        print("Found design!")
    else:
        print("No design found.")

